#!/usr/bin/env bash
set -Eeuo pipefail

DEST="$HOME/grantbot_installers/grantbot_v17_all_in_one.sh"
mkdir -p "$HOME/grantbot_installers"

cat <<'GRANTBOT_V17_PAYLOAD' | base64 -d | gzip -dc > "$DEST"

GRANTBOT_V17_PAYLOAD

chmod +x "$DEST"
bash -n "$DEST"
printf 'SAVED: %s\n' "$DEST"
printf 'SHA256: '
sha256sum "$DEST" | awk '{print $1}'
printf 'STARTING GRANTBOT V17...\n\n'

set +e
bash "$DEST"
RC=$?
set -e

printf '\nGrantBot V17 exited with code: %s\n' "$RC"
printf 'Saved installer remains at: %s\n' "$DEST"
exit "$RC"
